package com.opudas.paint.core.data.model

import kotlinx.serialization.Serializable

/*
 * The content bundle, as types.
 *
 * Every class here mirrors a JSON file under `assets/data/`, generated by
 * `tools/build-android-data.mjs` from the same `app/src/data/*.ts` modules the
 * website renders (ADR 0002: one source of truth, several consumers).
 *
 * Two rules are load-bearing:
 *
 *  1. A property is nullable or defaulted **only where the generator can
 *     actually omit it**. kotlinx.serialization throws on a missing key that has
 *     no default, so guessing "this is probably optional" turns a content edit
 *     into a crash on launch. Presence was measured across all 59 colours, 6
 *     products, 9 palettes, 19 projects, 6 guides, 14 dealers and the ten
 *     preparation situations before these types were written; the three genuinely
 *     optional fields are commented where they appear.
 *
 *  2. Nothing here carries behaviour. A colour is data. What a colour means for
 *     a room, a contrast ratio or a fan deck lives in `core/engine/`.
 */

/* ------------------------------------------------------------------ colours */

@Serializable
data class PaintColor(
    /** Where the value came from: a fan deck, a label, a screen proof. Shown, because a digital proof is not a chip. */
    val source: String,
    val id: String,
    val code: String,
    val name: String,
    val hex: String,
    val family: String,
    val undertone: String,
    val rooms: List<String>,
    val collection: String,
    val note: String,
    /** Light reflectance value: measured where it exists, estimated from the hex where it does not. */
    val lrv: Int,
)

@Serializable
data class ColorsBundle(
    val colors: List<PaintColor>,
    val families: List<String>,
    val rooms: List<String>,
    val collections: List<String>,
    /** The dot beside each family filter, keyed by family name. */
    val familySwatch: Map<String, String>,
)

/* ----------------------------------------------------------------- products */

@Serializable
data class Pack(
    val size: Double,
    val unit: String,
    val inStock: Boolean,
)

@Serializable
data class ProductDocument(
    val label: String,
    /** A web path; the app maps it onto its own bundled asset (see ContentRepository.documentAsset). */
    val href: String,
)

@Serializable
data class ApplicationStep(
    val step: String,
    val detail: String,
)

@Serializable
data class Product(
    val id: String,
    val sku: String,
    val name: String,
    val shortName: String,
    val line: String,
    val tagline: String,
    val description: String,
    val finish: String,
    val surfaces: List<String>,
    val sheenLevel: Int,
    /** m² per litre, or per kg for the screeding compound — hence a Double, and a unit on each pack. */
    val coveragePerUnit: Double,
    val coatsRecommended: Int,
    val touchDryHours: Int,
    val recoatHours: Int,
    val fullCureDays: Int,
    val dilution: String,
    val voc: String,
    val guaranteeYears: Int,
    val features: List<String>,
    val packs: List<Pack>,
    val image: String,
    val gallery: List<String>,
    val tds: List<ProductDocument>,
    val bestFor: String,
    val application: List<ApplicationStep>,
    /** `label-verified` or `pending-verification` — and the app renders the difference. */
    val claimsStatus: String,
)

@Serializable
data class ProductsBundle(
    val products: List<Product>,
    val sheenLabels: Map<String, String>,
)

/* ----------------------------------------------------------------- palettes */

@Serializable
data class Palette(
    val id: String,
    val name: String,
    val season: String,
    /** Colour ids, in the order the roles below describe. */
    val colors: List<String>,
    val roles: List<String>,
    val story: String,
    val bestFor: String,
    val image: String,
)

@Serializable
data class PalettesBundle(val palettes: List<Palette>)

/* ----------------------------------------------------------------- projects */

@Serializable
data class Project(
    val id: String,
    val title: String,
    val location: String,
    val year: String,
    /** `completed`, `in-progress` or `concept` — and concept work is labelled as concept everywhere it appears. */
    val stage: String,
    val kind: String,
    val summary: String,
    val story: List<String>,
    val cover: String,
    val gallery: List<String>,
    val colorIds: List<String>,
    val productIds: List<String>,
    val paletteId: String,
    val takeaway: String,
)

@Serializable
data class ProjectsBundle(val projects: List<Project>)

/* ------------------------------------------------------------------- guides */

@Serializable
data class GuideCallout(
    val title: String,
    val body: String,
    val tone: String,
)

@Serializable
data class GuideSection(
    val heading: String,
    val paragraphs: List<String>,
    /** Optional: 5 of the 19 sections across the six guides carry one. */
    val callout: GuideCallout? = null,
    /** Optional: 4 of 19. Rendered as bullets rather than paragraphs. */
    val list: List<String> = emptyList(),
)

@Serializable
data class GuideFaq(
    val q: String,
    val a: String,
)

@Serializable
data class Guide(
    val id: String,
    val title: String,
    val category: String,
    val summary: String,
    val readMinutes: Int,
    val updated: String,
    val reviewer: String,
    val hero: String,
    val sections: List<GuideSection>,
    val relatedColors: List<String>,
    val relatedProducts: List<String>,
    val faq: List<GuideFaq>,
)

@Serializable
data class GuidesBundle(
    val guides: List<Guide>,
    val categories: List<String>,
)

/* ------------------------------------------------------------------ dealers */

@Serializable
data class Dealer(
    val id: String,
    val name: String,
    val kind: String,
    val area: String,
    val city: String,
    val state: String,
    val lat: Double,
    val lng: Double,
    val services: List<String>,
    /**
     * Eight of fourteen are confirmed; six are representative trading areas the
     * commercial team has not signed off. The unverified ones render with "call
     * ahead to confirm stock" — the same words the website uses, because a dealer
     * who does not stock a product is a wasted journey for the customer.
     */
    val verified: Boolean,
    val hours: String,
)

@Serializable
data class BrandContact(
    val phoneDisplay: String,
    val phoneTel: String,
    val whatsapp: String,
)

@Serializable
data class DealersBundle(
    val dealers: List<Dealer>,
    val states: List<String>,
    val services: List<String>,
    val contact: BrandContact,
)

/* -------------------------------------------------------------------- tools */

@Serializable
data class ToolOption(
    val id: String,
    val label: String,
    val note: String,
)

@Serializable
data class ToolQuestion(
    val id: String,
    val step: String,
    val prompt: String,
    val why: String,
)

@Serializable
data class PrepStep(
    val step: String,
    val detail: String,
)

@Serializable
data class PrepSituation(
    val id: String,
    val label: String,
    val signs: List<String>,
    val surfaces: List<String>,
    val steps: List<PrepStep>,
    val products: List<String>,
    val guides: List<String>,
    val warnings: List<String>,
    /** Optional: 7 of the 10 situations map onto a finish-finder condition answer. */
    val condition: String? = null,
)

@Serializable
data class ToolCard(
    val id: String,
    /** A web route; the app maps it onto its own destination. */
    val to: String,
    val name: String,
    val summary: String,
    val roadmap: List<String>,
    val kind: String,
)

@Serializable
data class ToolsBundle(
    val surfaceOptions: List<ToolOption>,
    val conditionOptions: List<ToolOption>,
    val wearOptions: List<ToolOption>,
    val sheenOptions: List<ToolOption>,
    val finishQuestions: List<ToolQuestion>,
    val optionsFor: Map<String, List<ToolOption>>,
    val prepSituations: List<PrepSituation>,
    val toolCards: List<ToolCard>,
)

/* -------------------------------------------------------------------- media */

@Serializable
data class MediaEntry(
    /** Asset-relative path, e.g. `media/project-finished-villa.webp`. */
    val src: String,
    val thumb: String,
    val width: Int,
    val height: Int,
    val aspect: Double,
    /** The image's own dominant colour, shown as the placeholder while it decodes. */
    val tint: String,
    /**
     * Alt text, which in this repository is content rather than a component
     * detail (roadmap 09.02.02). All 49 images have some, and it is what
     * TalkBack reads, so an image without it is an image a blind customer
     * cannot use.
     */
    val alt: String,
)

@Serializable
data class MediaBundle(val images: Map<String, MediaEntry>)

/* -------------------------------------------------------------------- theme */

@Serializable
data class FontToken(
    val web: String,
    val android: String,
)

@Serializable
data class ThemeBundle(
    /** Token name to hex, straight out of `app/src/styles/theme.css`. */
    val colors: Map<String, String>,
    /** Token name to dp. */
    val radii: Map<String, Int>,
    val fonts: Map<String, FontToken>,
)
